// Satellite mesh (comes from satelite.html) and WebGL render onto a 3D billboard
const SAT_DATA={"pos": "", "nor": "", "col": "", "mat": "", "idx": "", "n": 8184};

(function(){
const c=document.getElementById('satc');if(!c)return;
const dpr=Math.min(window.devicePixelRatio||1,2),N=Math.round(280*dpr);c.width=c.height=N;
const x2=c.getContext('2d');
function fallback(){x2.clearRect(0,0,N,N);x2.save();x2.translate(N/2,N/2);x2.scale(dpr,dpr);
 x2.fillStyle='#4a58c8';x2.strokeStyle='#e8ecff';x2.lineWidth=1.5;
 [[-132,-16,100,32],[32,-16,100,32]].forEach(a=>{x2.fillRect(a[0],a[1],a[2],a[3]);x2.strokeRect(a[0],a[1],a[2],a[3])});
 x2.fillStyle='#e9ecf1';x2.fillRect(-26,-44,52,64);x2.fillStyle='#e0a84a';x2.fillRect(-26,-12,52,32);x2.fillStyle='#111';x2.beginPath();x2.arc(0,32,12,0,7);x2.fill();x2.restore()}
const off=document.createElement('canvas');off.width=off.height=N;
let gl=null;try{gl=off.getContext('webgl',{alpha:true,antialias:true})}catch(e){}
if(!gl){window.drawSat=fallback;return}
const b64=s=>{const b=atob(s),u=new Uint8Array(b.length);for(let i=0;i<b.length;i++)u[i]=b.charCodeAt(i);return u.buffer};
const VS=`attribute vec3 aPos;attribute vec3 aNor;attribute vec3 aCol;attribute vec2 aMat;uniform mat4 uMVP;uniform mat4 uView;varying vec3 vN;varying vec3 vCol;varying vec2 vMat;void main(){vN=mat3(uView)*aNor;vCol=aCol;vMat=aMat;gl_Position=uMVP*vec4(aPos,1.0);}`;
const FS=`precision mediump float;varying vec3 vN;varying vec3 vCol;varying vec2 vMat;void main(){vec3 n=normalize(vN);vec3 v=vec3(0.0,0.0,1.0);if(dot(n,v)<0.0)n=-n;vec3 L1=normalize(vec3(0.45,0.75,0.55));vec3 L2=normalize(vec3(-0.7,-0.2,0.4));float d1=max(dot(n,L1),0.0);float d2=max(dot(n,L2),0.0)*0.25;float hemi=0.5+0.5*n.y;vec3 h=normalize(L1+v);float spec=pow(max(dot(n,h),0.0),max(vMat.y,4.0))*vMat.x*0.9;gl_FragColor=vec4(vCol*(0.22+0.15*hemi+0.85*d1+d2)+vec3(spec),1.0);}`;
const sh=(t,src)=>{const s=gl.createShader(t);gl.shaderSource(s,src);gl.compileShader(s);return s};
const pr=gl.createProgram();gl.attachShader(pr,sh(gl.VERTEX_SHADER,VS));gl.attachShader(pr,sh(gl.FRAGMENT_SHADER,FS));gl.linkProgram(pr);
if(!gl.getProgramParameter(pr,gl.LINK_STATUS)){window.drawSat=fallback;return}
gl.useProgram(pr);
const at=(n,d,sz)=>{const b=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,b);gl.bufferData(gl.ARRAY_BUFFER,new Float32Array(b64(d)),gl.STATIC_DRAW);const l=gl.getAttribLocation(pr,n);gl.enableVertexAttribArray(l);gl.vertexAttribPointer(l,sz,gl.FLOAT,false,0,0)};
at('aPos',SAT_DATA.pos,3);at('aNor',SAT_DATA.nor,3);at('aCol',SAT_DATA.col,3);at('aMat',SAT_DATA.mat,2);
const ib=gl.createBuffer();gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER,ib);gl.bufferData(gl.ELEMENT_ARRAY_BUFFER,new Uint16Array(b64(SAT_DATA.idx)),gl.STATIC_DRAW);
const uM=gl.getUniformLocation(pr,'uMVP'),uV=gl.getUniformLocation(pr,'uView');
gl.enable(gl.DEPTH_TEST);gl.clearColor(0,0,0,0);gl.viewport(0,0,N,N);
const CEN=[0,.47,0],RAD=3.7;
function f(v,rx,rz){let x=v[0],y=v[2],z=v[1],a,b;
 a=x*Math.cos(rz)-y*Math.sin(rz);b=x*Math.sin(rz)+y*Math.cos(rz);x=a;y=b;
 a=y*Math.cos(rx)-z*Math.sin(rx);b=y*Math.sin(rx)+z*Math.cos(rx);y=a;z=b;return[x,-y,z]}
window.drawSat=function(rx,rz){
 const m=[[1,0,0],[0,1,0],[0,0,1]].map(e=>f(e,rx,rz)),t=f(CEN,rx,rz),mvp=[],vw=[];
 m.forEach(e=>{mvp.push(e[0]/RAD,e[1]/RAD,-e[2]/RAD,0);vw.push(e[0],e[1],e[2],0)});
 mvp.push(-t[0]/RAD,-t[1]/RAD,t[2]/RAD,1);vw.push(0,0,0,1);
 gl.uniformMatrix4fv(uM,false,new Float32Array(mvp));gl.uniformMatrix4fv(uV,false,new Float32Array(vw));
 gl.clear(gl.COLOR_BUFFER_BIT|gl.DEPTH_BUFFER_BIT);
 gl.drawElements(gl.TRIANGLES,SAT_DATA.n,gl.UNSIGNED_SHORT,0);
 x2.clearRect(0,0,N,N);x2.drawImage(off,0,0)};
})();
